      if (lookahead == '\t' ||
          lookahead == '\r' ||
          lookahead == ' ') ADVANCE(82);
      END_STATE();
    case 81:
      ACCEPT_TOKEN(sym__whitespace);
      if (lookahead == '|') ADVANCE(74);
      if (lookahead == '\t' ||
          lookahead == ' ') ADVANCE(81);
      if (lookahead == '\n' ||
          lookahead == '\r') ADVANCE(82);
      END_STATE();
    case 82:
      ACCEPT_TOKEN(sym__whitespace);
